// SET NX EX — only succeeds if key doesn't exist
// Returns null if lock already held → we stop execution
const lockKey = 'lock:wf10:signal_monitor';
const lockTTL = 21600;   // 6 hours in seconds

const result = await $helpers.redis.set(lockKey, $execution.id, 'EX', lockTTL, 'NX');

if (!result) {
  // Lock already held by another execution — stop gracefully
  throw new Error('WF10_LOCK_HELD: signal monitor already running, skipping this cycle');
}

return [{ json: { lock_key: lockKey, started_at: new Date().toISOString() } }];

// ── Signal detection logic ───────────────────────────────────────────────
// Spec thresholds:
//   hiring_spike      : employee_count growth > 20% vs stored value
//   funding_round     : new funding event since last_checked
//   website_change    : content diff > 30% vs stored homepage_hash
//   tech_stack_change : new positive tech signal added to stack
//
// Priority map (Improvement 2):
//   funding_round     → HIGH
//   hiring_spike      → HIGH
//   tech_stack_change → MEDIUM
//   website_change    → LOW

const SIGNAL_PRIORITY = {
  funding_round:     'HIGH',
  hiring_spike:      'HIGH',
  tech_stack_change: 'MEDIUM',
  website_change:    'LOW'
};

// Priority emoji for Slack messages
const PRIORITY_EMOJI = { HIGH: '🔴', MEDIUM: '🟡', LOW: '🟢' };

const company = $items('Set Signal Dedup Key')[0].json;

const safeJson = (item) => {
  try {
    const v = item?.json;
    return (typeof v === 'string') ? JSON.parse(v) : (v || {});
  } catch(_) { return {}; }
};

const apollo   = safeJson($items('Apollo — Org Enrichment')[0]);
const crunch   = safeJson($items('Crunchbase — Funding Data')[0]);
const jinaResp = $items('Jina — Website Scrape')[0]?.json || {};
const bwResp   = safeJson($items('BuiltWith — Tech Stack')[0]);

const signals = [];
const now     = new Date().toISOString();

// ── Signal 1: Hiring Spike ───────────────────────────────────────────────
const apolloOrg     = apollo.organization || apollo;
const newHeadcount  = parseInt(apolloOrg.num_employees || apolloOrg.employee_count || 0, 10);
const prevHeadcount = parseInt(company.employee_count || 0, 10);

if (prevHeadcount > 0 && newHeadcount > prevHeadcount * 1.20) {
  signals.push({
    signal_type: 'hiring_spike',
    source:      'apollo',
    evidence:    `Headcount grew from ${prevHeadcount} to ${newHeadcount} (+${Math.round((newHeadcount/prevHeadcount - 1) * 100)}%)`,
    new_value:   newHeadcount,
    prev_value:  prevHeadcount
  });
}

// ── Signal 2: Funding Round ──────────────────────────────────────────────
const crunchProps   = crunch.properties || crunch;
const fundingRounds = crunchProps.funding_rounds || [];
const lastChecked   = company.last_signal_check || company.updated_at || '2000-01-01';

const newFunding = fundingRounds.find(fr => {
  const announcedOn = fr.announced_on || fr.properties?.announced_on || '';
  return announcedOn > lastChecked;
});

if (newFunding) {
  const props  = newFunding.properties || newFunding;
  const amount = props.money_raised?.value_usd || props.raised_amount_usd || 0;
  const type   = props.investment_type || props.funding_type || 'funding';
  signals.push({
    signal_type: 'funding_round',
    source:      'crunchbase',
    evidence:    `New ${type} round: $${(amount / 1e6).toFixed(1)}M (announced ${props.announced_on || 'recently'})`,
    new_value:   JSON.stringify({ type, amount, announced_on: props.announced_on }),
    prev_value:  lastChecked
  });
}

// ── Signal 3: Website Change ─────────────────────────────────────────────
const pageContent = jinaResp.data?.content || jinaResp.content || jinaResp.text || '';
if (pageContent && pageContent.length > 100) {
  let hashVal = 0;
  const sample = pageContent.slice(0, 5000);
  for (let i = 0; i < sample.length; i++) hashVal = (hashVal * 31 + sample.charCodeAt(i)) >>> 0;
  const newHash  = hashVal.toString(36);
  const prevHash = company.homepage_hash || '';

  if (prevHash && newHash !== prevHash) {
    const prevLen = prevHash.length > 0 ? parseInt(prevHash.split('_')[1] || '0') : 0;
    const newLen  = pageContent.length;
    const diffPct = prevLen > 0 ? Math.abs(newLen - prevLen) / prevLen * 100 : 100;

    if (diffPct > 30 || !prevHash) {
      signals.push({
        signal_type: 'website_change',
        source:      'jina',
        evidence:    `Homepage content changed (hash: ${prevHash} → ${newHash}, ~${Math.round(diffPct)}% diff)`,
        new_value:   `${newHash}_${newLen}`,
        prev_value:  prevHash
      });
    }
  }
  company._new_homepage_hash = `${newHash}_${pageContent.length}`;
}

// ── Signal 4: Tech Stack Change ───────────────────────────────────────────
const bwResult = bwResp.Results?.[0]?.Result?.Paths?.[0]?.Technologies || [];
const newTechs = bwResult.map(t => (t.Name || t.name || '').toLowerCase()).filter(Boolean);
const prevTechStack = (() => {
  try {
    const v = company.tech_stack;
    if (!v) return [];
    return Array.isArray(v) ? v : JSON.parse(v);
  } catch(_) { return []; }
})();

const addedTechs = newTechs.filter(t => !prevTechStack.map(p => p.toLowerCase()).includes(t));

const HIGH_SIGNAL_TECHS = [
  'salesforce', 'hubspot', 'marketo', 'pardot', 'outreach', 'salesloft',
  'segment', 'amplitude', 'mixpanel', 'intercom', 'zendesk', 'drift',
  'gong', 'chorus', 'apollo', 'zoominfo', 'clay', 'clearbit',
  'greenhouse', 'lever', 'workday'
];

const highSignalAdded = addedTechs.filter(t =>
  HIGH_SIGNAL_TECHS.some(hs => t.includes(hs))
);

if (highSignalAdded.length > 0) {
  signals.push({
    signal_type: 'tech_stack_change',
    source:      'builtwith',
    evidence:    `New tech signals detected: ${highSignalAdded.join(', ')}`,
    new_value:   JSON.stringify(newTechs.slice(0, 50)),
    prev_value:  JSON.stringify(prevTechStack.slice(0, 50))
  });
}

// ── Attach priority to every signal and return ────────────────────────────
if (signals.length === 0) {
  return [{ json: {
    company_id:        company.id,
    company_name:      company.name,
    no_signals:        true,
    checked_at:        now,
    new_headcount:     newHeadcount,
    new_homepage_hash: company._new_homepage_hash || company.homepage_hash || null,
    new_tech_stack:    newTechs.length > 0 ? JSON.stringify(newTechs.slice(0, 50)) : null
  }}];
}

return signals.map(s => {
  const priority = SIGNAL_PRIORITY[s.signal_type] || 'LOW';
  return {
    json: {
      ...s,
      signal_priority:     priority,
      priority_emoji:      PRIORITY_EMOJI[priority],
      company_id:          company.id,
      company_name:        company.name,
      best_lead_id:        company.best_lead_id,
      best_lead_tier:      company.best_lead_tier,
      no_signals:          false,
      checked_at:          now,
      new_headcount:       newHeadcount    || null,
      new_homepage_hash:   company._new_homepage_hash || null,
      new_tech_stack:      newTechs.length > 0 ? JSON.stringify(newTechs.slice(0, 50)) : null
    }
  };
});

