const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-10';

// Release the run lock on error so next cycle can proceed
try {
  await $helpers.redis.del('lock:wf10:signal_monitor');
} catch(_) {}

return [{
  json: {
    status:       msg.includes('WF10_LOCK_HELD') ? 'lock_held' : 'error',
    message:      msg,
    workflow:     'WF-10',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];

